ers.GetLocal()	 	enemy = Input.GetNearestHeroToCursor(Entity.GetTeamNum(MyPlayerHero), Enum.TeamType.TEAM_ENEMY)      local NetherBlast = NPC.GetAbilityByIndex(MyPlayerHero, 0)     local Decrepify = NPC.GetAbilityByIndex(MyPlayerHero, 1)     local NWard = NPC.GetAbilityByIndex(MyPlayerHero, 2) 	local Lifedrain = NPC.GetAbility(MyPlayerHero, "pugna_life_drain")        local veil = NPC.GetItem(MyPlayerHero, "item_veil_of_discord", true)     local hex = NPC.GetItem(MyPlayerHero, "item_sheepstick", true)     local bloth = NPC.GetItem(MyPlayerHero, "item_bloodthorn", true)     local eblade = NPC.GetItem(MyPlayerHero, "item_ethereal_blade", true)     local orchid = NPC.GetItem(MyPlayerHero, "item_orchid", true)     local refresh = NPC.GetItem(MyPlayerHero, "item_refresher", true)     local RoA = NPC.GetItem(MyPlayerHero, "item_rod_of_atos", true)     local Sguard = NPC.GetItem(MyPlayerHero, "item_shivas_guard", true)     local Sring = NPC.GetItem(MyPlayerHero, "item_soul_ring", true)     local Fstaff = NPC.GetItem(MyPlayerHero, "item_force_staff", true)     local BladeM = NPC.GetItem(MyPlayerHero, "item_blade_mail", true)     local Hstaff = NPC.GetItem(MyPlayerHero, "item_hurricane_pike", true)     local EUL = NPC.GetItem(MyPlayerHero, "item_cyclone", true)     local shadowblyad = NPC.GetItem(MyPlayerHero, "item_invis_sword", true)     local silveredge = NPC.GetItem(MyPlayerHero, "item_silver_edge", true)     local glimmer = NPC.GetItem(MyPlayerHero, "item_glimmer_cape", true) 	local Mana = NPC.GetMana(MyPlayerHero)     local mousePos = Input.GetWorldCursorPos()     local heroPos = Entity.GetAbsOrigin(Target)     local heroAng = Entity.GetAbsRotation(Target)     local heroMs = NPC.GetMoveSpeed(Target)     local CP = Ability.GetCastPoint(Lifedrain)     local myPos = Entity.GetAbsOrigin(MyPlayerHero)     if not Menu.IsKeyDown(PugnaHx.optionHarrasKey) then return end     if NPC.HasState(Target, Enum.ModifierState.MODIFIER_STATE_MAGIC_IMMUNE) then return end         if Menu.IsEnabled(PugnaHx.optionHarrasEnableLinkens1) and Lifedrain and Ability.IsCastable(Lifedrain, Mana) and NPC.IsEntityInRange(Target, MyPlayerHero, Ability.GetCastRange(Lifedrain) - 10) and NPC.IsLinkensProtected(Target) and not Ability.IsInAbilityPhase(Lifedrain) then Ability.CastTarget(Lifedrain, Target); return end     if Menu.IsEnabled(PugnaHx.optionHarrasEnableLinkens2) and Decrepify and Ability.IsCastable(Decrepify, Mana) and NPC.IsEntityInRange(Target, MyPlayerHero, Ability.GetCastRange(Decrepify) - 10) and NPC.IsLinkensProtected(Target) and not Ability.IsInAbilityPhase(Lifedrain) then Ability.CastTarget(Decrepify, Target); return end     if Menu.IsEnabled(PugnaHx.optionHarrasEnableLinkens3) and Fstaff and Ability.IsCastable(Fstaff, Mana) and NPC.IsEntityInRange(Target, MyPlayerHero, Ability.GetCastRange(Fstaff) - 10) and NPC.IsLinkensProtected(Target) and not Ability.IsInAbilityPhase(Lifedrain) then Ability.CastTarget(Fstaff, Target); return end     if Menu.IsEnabled(PugnaHx.optionHarrasEnableLinkens4) and Hstaff and Ability.IsCastable(Hstaff, Mana) and NPC.IsEntityInRange(Target, MyPlayerHero, Ability.GetCastRange(Hstaff) - 10) and NPC.IsLinkensProtected(Target) and not Ability.IsInAbilityPhase(Lifedrain) then Ability.CastTarget(Hstaff, Target); return end     if Menu.IsEnabled(PugnaHx.optionHarrasEnableLinkens5) and EUL and Ability.IsCastable(EUL, Mana) and NPC.IsEntityInRange(Target, MyPlayerHero, Ability.GetCastRange(EUL) - 10) and NPC.IsLinkensProtected(Target) and not Ability.IsInAbilityPhase(Lifedrain) then Ability.CastTarget(EUL, Target); return end  	 	if not NPC.IsLinkensProtected(Target) and Menu.IsEnabled(PugnaHx.optionHarrasEnableVeil) and veil and Ability.IsCastable(veil, Mana) and NPC.IsEntityInRange(Target, MyPlayerHero, Ability.GetCastRange(veil) - 10) then Ability.CastPosition(veil, heroPos); return end 	 	if not NPC.IsLinkensProtected(Target) and Menu.IsEnabled(PugnaHx.optionHarrasEnableEblade) and eblade and Ability.IsCastable(eblade, Mana) 